import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Card dimensions based on image aspect ratio (512x320 ~ 1.6:1)
  const width = 2.4;
  const height = 1.5;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: '#e8ecf2', // paper placeholder until texture loads
  });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load the quote card texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
  });

  // Apply parallax-scroll cinematic primitive
  const primResult = ctx.primitives['parallax-scroll'](group, {
    intensity: 0.25,
  });

  // --- Interaction handlers ---
  const handlers = {
    pointerenter: () => {
      gsap.to(mesh.position, {
        y: 0.15,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    pointerleave: () => {
      gsap.to(mesh.position, {
        y: 0,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    click: () => {
      ctx.emit('hub-pricing.select');
    },
  };
  group.userData.handlers = handlers;

  // --- Cleanup ---
  group.userData.cleanup = () => {
    gsap.killTweensOf(mesh.position);
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    if (primResult && typeof primResult.cleanup === 'function') {
      primResult.cleanup();
    }
  };

  return group;
}
